INSERT INTO existing_subject_fixes VALUES ('0c6bdfd2-9685-4183-b32e-c202fcb78272'::uuid,'نبني ونبني',2,'00cc22a1-ded0-4858-85ec-25b246507de5'::uuid,3,580,25,34,'https://www.wepal.net/library/upload/03-2021/content/603e883c5c134.pdf',$actual0$[ضاديوم — تصحيح مضمون درس منشور بمقارنته مباشرة بكتاب لغتنا الجميلة]
المصدر: وزارة التربية والتعليم الفلسطينية، «لغتنا الجميلة»، الصف الثاني، الجزء الثاني، الدرس 3 «نبني ونبني»، الصفحات المطبوعة 25–34، الطبعة الرابعة المطبوعة 2020. النسخة الكاملة المعروضة على https://www.wepal.net/library/upload/03-2021/content/603e883c5c134.pdf.
تنويه: هذا النص شرح من تأليف ضاديوم لموضوع كتاب 2020، وليس نقلًا حرفيًا. لم تعتمد بعد مطابقته لكل تعديلات الطبعة الحالية 2026–2027 أو تسجيلات الاستماع الأصلية.

أولًا: أفهم أحداث الموضوع الوارد في الكتاب لا قصة خيالية بديلة
كان كريم يعيش مع أسرته في منزل قديم بالقدس انتقل إلى والده عن الجد. جاءت جرافة الاحتلال وهدمت المنزل أمام الطفل الحزين، فتبددت الغرف وتحول المكان إلى ركام. بكى كريم وهو يشاهد منزله يزول، فاحتضنه والده وطمأنه إلى أن الأسرة ستعيد البناء. أكدت الأم أنهم سيبقون ثابتين في مدينتهم ولن يتركوا القدس بسبب هدم البيت.
أتابع الشخصيات والمكان والسبب والنتيجة، وأشرح ماذا تغيّر في نهاية القصة. أفرق بين الوقائع المذكورة صراحة في النص وبين الاستنتاج الذي أخرج به بعد القراءة.

ثانيًا: أستنتج الفكرة الرئيسة والدروس المستفادة
يسلط النص الضوء على تعلق الأسرة بالبيت والمدينة وعلى الصمود والتمسك بالأمل مع الحزن على فقدان المنزل.
أختار حدثين وأربطهما بعلاقة السبب والنتيجة. أستطيع تفسير معنى العنوان بالاعتماد على ما حدث بالفعل، وأذكر تفصيلًا واحدًا من القصة يؤيد تفسيري. وعند طرح رأي أقدمه بوصفه رأيًا شخصيًا لا حدثًا في النص.

ثالثًا: أوسع مفرداتي وأستخدمها بطريقة صحيحة
الجرافة: آلة ثقيلة تحرك التراب والحجارة؛ الركام: ما يتبقى من بناء مهدوم؛ صامد: ثابت لا يتراجع؛ ورث: انتقل إليه الشيء عن شخص من العائلة؛ انهار: سقط بعد أن كان قائمًا.
أختار كلمتين من الشرح وأضعهما في جملتين جديدتين. أشرح لماذا تلائم المفردة هذا الحدث وأميز الكلمة عن أخرى تشبهها في اللفظ وتختلف عنها في المعنى.

رابعًا: أتمرن على مهارة لغوية من موضوع القراءة
أميز التاء المربوطة من المبسوطة في كلمات مثل «غرفة» و«بيت» و«حجارة»، وأكتب جملة تصف المكان قبل الهدم وبعده مستخدمًا الماضي.
أقرأ الجمل بصوت واضح وأكتب مثالًا من عندي، ثم أعرضه على المعلم ليتحقق من صحة التراكيب والحركات. هذه أمثلة جديدة من ضاديوم ولا أدعي أنها كل التدريبات الوزارية المصورة.

خامسًا: أجيب وأكتب عن درس الكتاب
أين كان منزل كريم؟ ممن ورثه والده؟ ماذا حدث للغرف؟ كيف حاول الأب تهدئة كريم؟ ماذا قررت الأم؟
أجيب بجملة مفيدة وأذكر دليلًا من الأحداث، ثم أكتب تلخيصًا قصيرًا يذكر بداية القصة والمشكلة والنتيجة. إذا طلب المعلم الاستماع أو الإنشاد أراجع المصدر الأصلي، فلا أكتفي بوجود عنوان الدرس أو عدد أنشطته.

سادسًا: أميز القراءة من الاستماع
الاستماع نص منفصل، والشرح هنا لأحداث نص «نبني ونبني» المقروء.
لا يغني هذا الشرح عن مراجعة الصورة المقابلة للنص ودليل المعلم وأي مادة مسموعة مرتبطة بالدروس في الطبعة المعتمدة.

[نهاية تصحيح نص الدرس المدرسي الفعلي، طبعة 2020]$actual0$,'["أن يشرح الطالب أحداث نص «نبني ونبني» الحقيقي مع الشخصيات والسبب والنتيجة.","أن يفسر الطالب ثلاث مفردات ويستشهد بتفصيل من النص يوضح الفكرة الرئيسة.","أن يكتب الطالب تلخيصًا موجزًا ويوظف مهارة لغوية مرتبطة بالدرس في مثالين."]'::jsonb),
('1148944d-d95d-48e0-923f-dcb86a7f84c7'::uuid,'العصفورة والأفعى',2,'00cc22a1-ded0-4858-85ec-25b246507de5'::uuid,4,592,35,44,'https://www.wepal.net/library/upload/03-2021/content/603e883c5c134.pdf',$actual1$[ضاديوم — تصحيح مضمون درس منشور بمقارنته مباشرة بكتاب لغتنا الجميلة]
المصدر: وزارة التربية والتعليم الفلسطينية، «لغتنا الجميلة»، الصف الثاني، الجزء الثاني، الدرس 4 «العصفورة والأفعى»، الصفحات المطبوعة 35–44، الطبعة الرابعة المطبوعة 2020. النسخة الكاملة المعروضة على https://www.wepal.net/library/upload/03-2021/content/603e883c5c134.pdf.
تنويه: هذا النص شرح من تأليف ضاديوم لموضوع كتاب 2020، وليس نقلًا حرفيًا. لم تعتمد بعد مطابقته لكل تعديلات الطبعة الحالية 2026–2027 أو تسجيلات الاستماع الأصلية.

أولًا: أفهم أحداث الموضوع الوارد في الكتاب لا قصة خيالية بديلة
ذهبت عصفورة إلى حمامة صديقتها تستشيرها في مشكلة متكررة؛ فقد كانت أفعى تتسلق الشجرة وتلتهم البيض والفراخ بعد فقسها. طلبت العصفورة حيلة تحمي بها صغارها. فكرت الحمامة في حل لا يقوم على مواجهة الأفعى، واقترحت أن تبني العصفورة عشها فوق شجرة عالية في حديقة عامة يزورها الناس؛ فالأفعى تخشى وجود البشر فتبتعد عن المكان.
أتابع الشخصيات والمكان والسبب والنتيجة، وأشرح ماذا تغيّر في نهاية القصة. أفرق بين الوقائع المذكورة صراحة في النص وبين الاستنتاج الذي أخرج به بعد القراءة.

ثانيًا: أستنتج الفكرة الرئيسة والدروس المستفادة
تتناول القصة حب الأم لصغارها والتفكير الهادئ والاستفادة من رأي صديق مخلص بدل الدخول في مواجهة خطرة.
أختار حدثين وأربطهما بعلاقة السبب والنتيجة. أستطيع تفسير معنى العنوان بالاعتماد على ما حدث بالفعل، وأذكر تفصيلًا واحدًا من القصة يؤيد تفسيري. وعند طرح رأي أقدمه بوصفه رأيًا شخصيًا لا حدثًا في النص.

ثالثًا: أوسع مفرداتي وأستخدمها بطريقة صحيحة
الأفعى: نوع من الثعابين؛ الفرخ: صغير الطائر؛ الفقس: خروج الصغير من البيضة؛ العش: مأوى الطائر؛ الحديقة العامة: مكان يزوره الناس للتنزه.
أختار كلمتين من الشرح وأضعهما في جملتين جديدتين. أشرح لماذا تلائم المفردة هذا الحدث وأميز الكلمة عن أخرى تشبهها في اللفظ وتختلف عنها في المعنى.

رابعًا: أتمرن على مهارة لغوية من موضوع القراءة
أستخدم حرف الجر «في» مع المكان الذي توجد بداخله الأشياء، و«على» للموقع فوق شيء. وأميز التاء المربوطة في «عصفورة» من الهاء في آخر «فيه».
أقرأ الجمل بصوت واضح وأكتب مثالًا من عندي، ثم أعرضه على المعلم ليتحقق من صحة التراكيب والحركات. هذه أمثلة جديدة من ضاديوم ولا أدعي أنها كل التدريبات الوزارية المصورة.

خامسًا: أجيب وأكتب عن درس الكتاب
إلى من ذهبت العصفورة؟ ماذا كانت تفعل الأفعى؟ لماذا نصحت الحمامة بحديقة يرتادها الناس؟ ما حل المشكلة؟ كيف نعامل أعشاش الطيور؟
أجيب بجملة مفيدة وأذكر دليلًا من الأحداث، ثم أكتب تلخيصًا قصيرًا يذكر بداية القصة والمشكلة والنتيجة. إذا طلب المعلم الاستماع أو الإنشاد أراجع المصدر الأصلي، فلا أكتفي بوجود عنوان الدرس أو عدد أنشطته.

سادسًا: أميز القراءة من الاستماع
موضوع القراءة عن حماية العش من الأفعى، ولا أضيف إليه وقائع غير مذكورة في الكتاب.
لا يغني هذا الشرح عن مراجعة الصورة المقابلة للنص ودليل المعلم وأي مادة مسموعة مرتبطة بالدروس في الطبعة المعتمدة.

[نهاية تصحيح نص الدرس المدرسي الفعلي، طبعة 2020]$actual1$,'["أن يشرح الطالب أحداث نص «العصفورة والأفعى» الحقيقي مع الشخصيات والسبب والنتيجة.","أن يفسر الطالب ثلاث مفردات ويستشهد بتفصيل من النص يوضح الفكرة الرئيسة.","أن يكتب الطالب تلخيصًا موجزًا ويوظف مهارة لغوية مرتبطة بالدرس في مثالين."]'::jsonb),
('920d781e-7051-46a0-aad0-33ec3ca360e5'::uuid,'في مدينة الخليل',2,'00cc22a1-ded0-4858-85ec-25b246507de5'::uuid,5,620,45,54,'https://www.wepal.net/library/upload/03-2021/content/603e883c5c134.pdf',$actual2$[ضاديوم — تصحيح مضمون درس منشور بمقارنته مباشرة بكتاب لغتنا الجميلة]
المصدر: وزارة التربية والتعليم الفلسطينية، «لغتنا الجميلة»، الصف الثاني، الجزء الثاني، الدرس 5 «في مدينة الخليل»، الصفحات المطبوعة 45–54، الطبعة الرابعة المطبوعة 2020. النسخة الكاملة المعروضة على https://www.wepal.net/library/upload/03-2021/content/603e883c5c134.pdf.
تنويه: هذا النص شرح من تأليف ضاديوم لموضوع كتاب 2020، وليس نقلًا حرفيًا. لم تعتمد بعد مطابقته لكل تعديلات الطبعة الحالية 2026–2027 أو تسجيلات الاستماع الأصلية.

أولًا: أفهم أحداث الموضوع الوارد في الكتاب لا قصة خيالية بديلة
رافقَت علياء خالها عدنان في جولة بالبلدة القديمة في مدينة الخليل. مرا بشارع الشلالة وبقرب مدرسة أسامة، وتحدث النص عن أثر السيطرة على أحد المباني التاريخية. شاهدا الأسواق التي تضم الخضروات والملابس الشعبية والعطارة والحلويات، إلى جانب صناعة الأحذية. زارا كذلك تكية سيدنا إبراهيم الخليل قرب الحرم الإبراهيمي، وتعرفت علياء خلال الجولة إلى جوانب من تراث المدينة ومعالمها.
أتابع الشخصيات والمكان والسبب والنتيجة، وأشرح ماذا تغيّر في نهاية القصة. أفرق بين الوقائع المذكورة صراحة في النص وبين الاستنتاج الذي أخرج به بعد القراءة.

ثانيًا: أستنتج الفكرة الرئيسة والدروس المستفادة
موضوع الدرس رحلة تعريفية إلى الخليل وأسواقها وحرفها ومعالمها، وليس وصفًا عامًا لأي مدينة أو منتزه.
أختار حدثين وأربطهما بعلاقة السبب والنتيجة. أستطيع تفسير معنى العنوان بالاعتماد على ما حدث بالفعل، وأذكر تفصيلًا واحدًا من القصة يؤيد تفسيري. وعند طرح رأي أقدمه بوصفه رأيًا شخصيًا لا حدثًا في النص.

ثالثًا: أوسع مفرداتي وأستخدمها بطريقة صحيحة
البلدة القديمة: الجزء التاريخي من المدينة؛ العطارة: تجارة العطور والمواد العشبية؛ التكية: مكان يقدم الطعام أو المساعدة للمحتاجين؛ الحرفة: مهنة تعتمد مهارة؛ المعلم: مكان تاريخي معروف.
أختار كلمتين من الشرح وأضعهما في جملتين جديدتين. أشرح لماذا تلائم المفردة هذا الحدث وأميز الكلمة عن أخرى تشبهها في اللفظ وتختلف عنها في المعنى.

رابعًا: أتمرن على مهارة لغوية من موضوع القراءة
أستخدم حرفي الجر «إلى» و«في» بدقة، وأكتب وصفًا لمكان يبدأ بالاسم ثم يذكر موقعه وما يشتهر به. أميز الاسم المعرف بـ«الـ» من النكرة في جمل قصيرة.
أقرأ الجمل بصوت واضح وأكتب مثالًا من عندي، ثم أعرضه على المعلم ليتحقق من صحة التراكيب والحركات. هذه أمثلة جديدة من ضاديوم ولا أدعي أنها كل التدريبات الوزارية المصورة.

خامسًا: أجيب وأكتب عن درس الكتاب
من رافق علياء؟ ما اسم المدينة؟ اذكر سوقين شاهدتهما؟ ما الحرف التي وردت في الدرس؟ لماذا ينبغي المحافظة على مباني المدن التاريخية؟
أجيب بجملة مفيدة وأذكر دليلًا من الأحداث، ثم أكتب تلخيصًا قصيرًا يذكر بداية القصة والمشكلة والنتيجة. إذا طلب المعلم الاستماع أو الإنشاد أراجع المصدر الأصلي، فلا أكتفي بوجود عنوان الدرس أو عدد أنشطته.

سادسًا: أميز القراءة من الاستماع
الكتاب يخصص نص استماع بعنوان «رحلة إلى بيت لحم»؛ لذا لا أخلط بين زيارة علياء للخليل وبين أحداث رحلة بيت لحم.
لا يغني هذا الشرح عن مراجعة الصورة المقابلة للنص ودليل المعلم وأي مادة مسموعة مرتبطة بالدروس في الطبعة المعتمدة.

[نهاية تصحيح نص الدرس المدرسي الفعلي، طبعة 2020]$actual2$,'["أن يشرح الطالب أحداث نص «في مدينة الخليل» الحقيقي مع الشخصيات والسبب والنتيجة.","أن يفسر الطالب ثلاث مفردات ويستشهد بتفصيل من النص يوضح الفكرة الرئيسة.","أن يكتب الطالب تلخيصًا موجزًا ويوظف مهارة لغوية مرتبطة بالدرس في مثالين."]'::jsonb),
